from collections import Counter
from typing import List

class Solution:
    def largestOverlap(self, img1: List[List[int]], img2: List[List[int]]) -> int:
        n = len(img1)
        pts1 = [(r, c) for r in range(n) for c in range(n) if img1[r][c] == 1]
        pts2 = [(r, c) for r in range(n) for c in range(n) if img2[r][c] == 1]
        if not pts1 or not pts2:
            return 0
        diffs = Counter((r1 - r2, c1 - c2) for r1, c1 in pts1 for r2, c2 in pts2)
        return max(diffs.values())

class Solution {
public:
    int largestOverlap(vector<vector<int>>& img1, vector<vector<int>>& img2) {
        int n = img1.size();
        vector<pair<int, int>> pts1, pts2;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (img1[r][c] == 1) pts1.push_back({r, c});
                if (img2[r][c] == 1) pts2.push_back({r, c});
            }
        }
        if (pts1.empty() || pts2.empty()) return 0;
        map<pair<int, int>, int> counts;
        int ans = 0;
        for (const auto& p1 : pts1) {
            for (const auto& p2 : pts2) {
                pair<int, int> delta = {p1.first - p2.first, p1.second - p2.second};
                counts[delta]++;
                ans = max(ans, counts[delta]);
            }
        }
        return ans;
    }
};

class Solution {
    public int largestOverlap(int[][] img1, int[][] img2) {
        int n = img1.length;
        List<int[]> pts1 = new ArrayList<>();
        List<int[]> pts2 = new ArrayList<>();
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (img1[r][c] == 1) pts1.add(new int[]{r, c});
                if (img2[r][c] == 1) pts2.add(new int[]{r, c});
            }
        }
        if (pts1.isEmpty() || pts2.isEmpty()) return 0;
        Map<String, Integer> counts = new HashMap<>();
        int ans = 0;
        for (int[] p1 : pts1) {
            for (int[] p2 : pts2) {
                String key = (p1[0] - p2[0]) + "," + (p1[1] - p2[1]);
                int cnt = counts.getOrDefault(key, 0) + 1;
                counts.put(key, cnt);
                ans = Math.max(ans, cnt);
            }
        }
        return ans;
    }
}

var largestOverlap = function(img1, img2) {
    const n = img1.length;
    const pts1 = [];
    const pts2 = [];
    for (let r = 0; r < n; r++) {
        for (let c = 0; c < n; c++) {
            if (img1[r][c] === 1) pts1.push([r, c]);
            if (img2[r][c] === 1) pts2.push([r, c]);
        }
    }
    if (pts1.length === 0 || pts2.length === 0) return 0;
    const counts = new Map();
    let ans = 0;
    for (const [r1, c1] of pts1) {
        for (const [r2, c2] of pts2) {
            const key = `${r1 - r2},${c1 - c2}`;
            const cnt = (counts.get(key) || 0) + 1;
            counts.set(key, cnt);
            if (cnt > ans) ans = cnt;
        }
    }
    return ans;
};
